module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] pick;
    logic       any;
    always_comb begin
        pick = last;
        any  = 1'b0;
        for (int k = 4; k >= 1; k--) begin
            if (req[2'(last + 2'(k))]) begin
                pick = 2'(last + 2'(k));
                any  = 1'b1;
            end
        end
    end
    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= '0;
            last <= 2'd3;
        end else if (!any) begin
            gnt  <= '0;
        end else begin
            gnt  <= 4'b0001 << pick;
            last <= pick;
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int FLIT_W = 4 + PAYLOAD_W;
    localparam logic [2:0] NORTH = 3'd0;
    localparam logic [2:0] SOUTH = 3'd1;
    localparam logic [2:0] EAST  = 3'd2;
    localparam logic [2:0] WEST  = 3'd3;
    localparam logic [2:0] LOCAL_PORT = 3'd4;

    logic [2:0] route [5];
    logic [4:0] accepted [5];

    for (genvar src = 0; src < 5; src++) begin : g_route
        wire [1:0] dest_x = in_flit[src*FLIT_W + PAYLOAD_W+2 +: 2];
        wire [1:0] dest_y = in_flit[src*FLIT_W + PAYLOAD_W +: 2];
        assign route[src] = dest_x > X ? EAST :
                            dest_x < X ? WEST :
                            dest_y > Y ? NORTH :
                            dest_y < Y ? SOUTH : LOCAL_PORT;
        assign in_ready[src] = accepted[0][src] | accepted[1][src] | accepted[2][src] |
                               accepted[3][src] | accepted[4][src];
    end

    for (genvar dst = 0; dst < 5; dst++) begin : g_output
        logic occupied;
        logic [FLIT_W-1:0] data;
        logic [2:0] cursor;
        logic [2:0] slot_succ;
        logic [4:0] requests, grant;
        logic [FLIT_W-1:0] selected_flit;
        logic [2:0] gsrc;
        logic [2:0] start;
        logic can_accept;
        logic drain;

        assign drain = occupied && out_ready[dst];
        assign can_accept = !rst && (!occupied || out_ready[dst]);
        assign start = occupied ? slot_succ : cursor;

        assign out_valid[dst] = occupied;
        assign out_flit[dst*FLIT_W +: FLIT_W] = occupied ? data : '0;
        assign accepted[dst] = grant;

        for (genvar src = 0; src < 5; src++) begin : g_req
            assign requests[src] = in_valid[src] && route[src] == 3'(dst);
        end

        always_comb begin
            int k;
            logic found;
            grant = '0;
            gsrc = 3'd0;
            found = 1'b0;
            for (int i = 0; i < 5; i++) begin
                k = int'(start) + i;
                if (k >= 5) k = k - 5;
                if (!found && can_accept && requests[k]) begin
                    found = 1'b1;
                    grant[k] = 1'b1;
                    gsrc = 3'(k);
                end
            end
            selected_flit = '0;
            for (int s = 0; s < 5; s++) begin
                selected_flit |= in_flit[s*FLIT_W +: FLIT_W] & {FLIT_W{grant[s]}};
            end
        end

        always_ff @(posedge clk) begin
            if (rst) begin
                occupied  <= 1'b0;
                cursor    <= 3'd0;
                slot_succ <= 3'd0;
                data      <= '0;
            end else begin
                if (drain) cursor <= slot_succ;
                if (|grant) begin
                    occupied  <= 1'b1;
                    data      <= selected_flit;
                    slot_succ <= (gsrc == 3'd4) ? 3'd0 : gsrc + 3'd1;
                end else if (drain) begin
                    occupied <= 1'b0;
                end
            end
        end
    end
endmodule

module axi4_burst_slave #(
    parameter int ADDR_W = 8,
    parameter int ID_W   = 2,
    parameter int LEN_W  = 8
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    output logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    output logic              s_axi_wready,

    output logic [ID_W-1:0]   s_axi_bid,
    output logic [1:0]        s_axi_bresp,
    output logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    output logic              s_axi_arready,

    output logic [ID_W-1:0]   s_axi_rid,
    output logic [31:0]       s_axi_rdata,
    output logic [1:0]        s_axi_rresp,
    output logic              s_axi_rlast,
    output logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    localparam int WORDS = 1 << (ADDR_W - 2);
    localparam int RANGE_W = 1 + ((ADDR_W > LEN_W + 2) ? ADDR_W : LEN_W + 2);
    localparam logic [1:0] OKAY = 2'b00, SLVERR = 2'b10;

    logic unused_attrs;
    assign unused_attrs = ^{s_axi_awcache, s_axi_awprot, s_axi_awqos, s_axi_awregion,
                            s_axi_arcache, s_axi_arprot, s_axi_arqos, s_axi_arregion};

    function automatic logic bad_burst(
        input logic [ADDR_W-1:0] addr,
        input logic [LEN_W-1:0] len,
        input logic [2:0] size,
        input logic [1:0] burst,
        input logic lock
    );
        logic [RANGE_W-1:0] last_addr;
        last_addr = RANGE_W'(addr) + (RANGE_W'(len) << 2);
        bad_burst = addr[1:0] != 2'b00 || size != 3'd2 || burst != 2'b01 || lock
                    || (last_addr >> ADDR_W) != '0;
    endfunction

    logic [31:0] memory [WORDS];
    logic write_active, write_bad, last_bad;
    logic [ID_W-1:0] write_id;
    logic [LEN_W-1:0] write_rem, read_rem;
    logic [ADDR_W-3:0] write_word, next_read_word;
    logic aw_fire, w_fire, ar_fire, r_fire;
    logic aw_bad, ar_bad;
    assign aw_fire = s_axi_awvalid && s_axi_awready;
    assign w_fire = s_axi_wvalid && s_axi_wready;
    assign ar_fire = s_axi_arvalid && s_axi_arready;
    assign r_fire = s_axi_rvalid && s_axi_rready;
    assign aw_bad = bad_burst(s_axi_awaddr, s_axi_awlen, s_axi_awsize, s_axi_awburst, s_axi_awlock);
    assign ar_bad = bad_burst(s_axi_araddr, s_axi_arlen, s_axi_arsize, s_axi_arburst, s_axi_arlock);
    assign s_axi_arready = !rst && !s_axi_rvalid;

    assign s_axi_awready = !rst && !write_active && !s_axi_bvalid;
    assign s_axi_wready = !rst && write_active;
    assign last_bad = s_axi_wlast != (write_rem == '0);


    always_ff @(posedge clk) begin
        if (rst) begin
            write_active <= 1'b0;
            write_bad <= 1'b0;
            write_id <= '0;
            write_rem <= '0;
            write_word <= '0;
            s_axi_bvalid <= 1'b0;
            s_axi_bid <= '0;
            for (int word_idx = 0; word_idx < WORDS; word_idx++)
                memory[word_idx] <= '0;
        end else begin
            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;
            if (aw_fire) begin
                write_active <= 1'b1;
                write_bad <= aw_bad;
                write_id <= s_axi_awid;
                write_rem <= s_axi_awlen;
                write_word <= s_axi_awaddr[ADDR_W-1:2];
            end
            if (w_fire) begin
                if (!write_bad) begin
                    for (int lane = 0; lane < 4; lane++) begin
                        if (s_axi_wstrb[lane])
                            memory[write_word][8*lane +: 8] <= s_axi_wdata[8*lane +: 8];
                    end
                end
                if (write_rem == '0) begin
                    write_active <= 1'b0;
                    s_axi_bvalid <= 1'b1;
                    s_axi_bid <= write_id;
                end else begin
                    write_rem <= write_rem - 1'b1;
                    write_word <= write_word + 1'b1;
                end
            end
        end
    end


    logic bad_last_seen;
    always_ff @(posedge clk) begin
        if (rst) begin
            bad_last_seen <= 1'b0;
            s_axi_bresp <= OKAY;
        end else begin
            if (aw_fire)
                bad_last_seen <= 1'b0;
            if (w_fire) begin
                bad_last_seen <= bad_last_seen || last_bad;
                if (write_rem == '0)
                    s_axi_bresp <= (write_bad || bad_last_seen || last_bad) ? SLVERR : OKAY;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            s_axi_rvalid <= 1'b0;
            s_axi_rid <= '0;
            s_axi_rdata <= '0;
            s_axi_rlast <= 1'b0;
            s_axi_rresp <= OKAY;
            read_rem <= '0;
            next_read_word <= '0;
        end else if (ar_fire) begin
            s_axi_rvalid <= 1'b1;
            s_axi_rid <= s_axi_arid;
            s_axi_rresp <= ar_bad ? SLVERR : OKAY;
            s_axi_rdata <= ar_bad ? 32'b0 : memory[s_axi_araddr[ADDR_W-1:2]];
            s_axi_rlast <= s_axi_arlen == '0;
            read_rem <= s_axi_arlen;
            next_read_word <= s_axi_araddr[ADDR_W-1:2] + 1'b1;
        end else if (r_fire) begin
            if (s_axi_rlast) begin
                s_axi_rvalid <= 1'b0;
            end else begin
                read_rem <= read_rem - 1'b1;
                next_read_word <= next_read_word + 1'b1;
                s_axi_rdata <= (s_axi_rresp == OKAY) ? memory[next_read_word] : 32'b0;
                s_axi_rlast <= read_rem == LEN_W'(1);
            end
        end
    end
endmodule

module cache_controller #(
    parameter int DATA_W = 32,
    parameter int TAG_W = 5,
    parameter int INDEX_W = 2
) (
    input  logic                     clk,
    input  logic                     rst,
    input  logic                     inv_valid,
    output logic                     inv_ready,
    input  logic                     cpu_req_valid,
    output logic                     cpu_req_ready,
    input  logic [TAG_W+INDEX_W:0]   cpu_req_addr,
    output logic                     cpu_rsp_valid,
    input  logic                     cpu_rsp_ready,
    output logic [DATA_W-1:0]        cpu_rsp_data,
    output logic                     mem_req_valid,
    input  logic                     mem_req_ready,
    output logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input  logic                     mem_rsp_valid,
    output logic                     mem_rsp_ready,
    input  logic [2*DATA_W-1:0]      mem_rsp_data
);
    localparam int LINES = 1 << INDEX_W;
    typedef enum logic [1:0] { IDLE, SEND_REQUEST, WAIT_REFILL, RESPOND } phase_t;
    phase_t phase;

    logic [LINES-1:0] valid;
    logic [2*DATA_W-1:0] lines [LINES];
    logic [TAG_W-1:0] tags [LINES];
    logic [TAG_W+INDEX_W-1:0] pending_line;
    logic pending_offset;
    logic [DATA_W-1:0] response;

    wire [INDEX_W-1:0] request_index = cpu_req_addr[INDEX_W:1];
    wire [TAG_W-1:0] request_tag = cpu_req_addr[TAG_W+INDEX_W:INDEX_W+1];
    wire [INDEX_W-1:0] pending_index = pending_line[INDEX_W-1:0];
    wire [TAG_W-1:0] pending_tag = pending_line[TAG_W+INDEX_W-1:INDEX_W];
    wire hit = valid[request_index] && (tags[request_index] == request_tag);
    wire request_offset = cpu_req_addr[0];
    wire [2*DATA_W-1:0] hit_line = lines[request_index];

    assign inv_ready = !rst && phase == IDLE;
    assign cpu_req_ready = inv_ready && !inv_valid;
    assign cpu_rsp_valid = !rst && phase == RESPOND;
    assign cpu_rsp_data = cpu_rsp_valid ? response : '0;
    assign mem_req_valid = !rst && phase == SEND_REQUEST;
    assign mem_req_addr = mem_req_valid ? pending_line : '0;
    assign mem_rsp_ready = !rst && phase == WAIT_REFILL;

    always_ff @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            valid <= '0;
            pending_line <= '0;
            pending_offset <= 1'b0;
            response <= '0;
        end else begin
            case (phase)
                IDLE: begin
                    if (inv_valid) begin
                        valid <= '0;
                    end else if (cpu_req_valid) begin
                        if (hit) begin
                            response <= request_offset ? hit_line[2*DATA_W-1:DATA_W] : hit_line[DATA_W-1:0];
                            phase <= RESPOND;
                        end else begin
                            pending_line <= cpu_req_addr[TAG_W+INDEX_W:1];
                            pending_offset <= request_offset;
                            phase <= SEND_REQUEST;
                        end
                    end
                end
                SEND_REQUEST: if (mem_req_ready) phase <= WAIT_REFILL;
                WAIT_REFILL: if (mem_rsp_valid) begin
                    valid[pending_index] <= 1'b1;
                    tags[pending_index] <= pending_tag;
                    lines[pending_index] <= mem_rsp_data;
                    response <= pending_offset ? mem_rsp_data[2*DATA_W-1:DATA_W] : mem_rsp_data[DATA_W-1:0];
                    phase <= RESPOND;
                end
                RESPOND: if (cpu_rsp_ready) phase <= IDLE;
                default: phase <= IDLE;
            endcase
        end
    end
endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);
    localparam logic [1:0] OKAY = 2'b00;
    localparam logic [1:0] SLVERR = 2'b10;

    logic [31:0] ctrl, scratch, irq;
    logic have_aw, have_w, commit_write;
    logic [3:0] addr_q, strb_q;
    logic [31:0] data_q, byte_en;
    logic unused_prot;

    assign unused_prot = ^{s_axi_awprot, s_axi_arprot};
    assign s_axi_awready = !rst && !have_aw && !s_axi_bvalid;
    assign s_axi_wready = !rst && !have_w && !s_axi_bvalid;
    assign s_axi_arready = !rst && !s_axi_rvalid;
    assign commit_write = have_aw && have_w;

    for (genvar lane = 0; lane < 4; lane++) begin : gen_byte_en
        assign byte_en[8*lane +: 8] = {8{strb_q[lane]}};
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl <= '0;
            scratch <= '0;
            irq <= '0;
            have_aw <= 1'b0;
            have_w <= 1'b0;
            addr_q <= '0;
            data_q <= '0;
            strb_q <= '0;
            s_axi_bresp <= OKAY;
            s_axi_bvalid <= 1'b0;
            s_axi_rdata <= '0;
            s_axi_rresp <= OKAY;
            s_axi_rvalid <= 1'b0;
        end else begin
            irq <= irq | irq_set;

            if (s_axi_awvalid && s_axi_awready) begin
                have_aw <= 1'b1;
                addr_q <= s_axi_awaddr;
            end
            if (s_axi_wvalid && s_axi_wready) begin
                have_w <= 1'b1;
                data_q <= s_axi_wdata;
                strb_q <= s_axi_wstrb;
            end

            if (s_axi_bvalid && s_axi_bready)
                s_axi_bvalid <= 1'b0;

            if (commit_write) begin
                have_aw <= 1'b0;
                have_w <= 1'b0;
                s_axi_bvalid <= 1'b1;
                s_axi_bresp <= OKAY;
                case (addr_q)
                    4'h0: ctrl <= (ctrl & ~byte_en) | (data_q & byte_en);
                    4'h8: scratch <= (scratch & ~byte_en) | (data_q & byte_en);
                    4'hc: irq <= (irq & ~(data_q & byte_en)) | irq_set;
                    default: s_axi_bresp <= SLVERR;
                endcase
            end

            if (s_axi_rvalid && s_axi_rready)
                s_axi_rvalid <= 1'b0;

            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rresp <= OKAY;
                case (s_axi_araddr)
                    4'h0: s_axi_rdata <= ctrl;
                    4'h4: s_axi_rdata <= status_in;
                    4'h8: s_axi_rdata <= scratch;
                    4'hc: s_axi_rdata <= irq;
                    default: begin
                        s_axi_rdata <= '0;
                        s_axi_rresp <= SLVERR;
                    end
                endcase
            end
        end
    end
endmodule

module gearbox_16to12 #(
    parameter integer UNIT_W = 4
) (
    input  logic                clk,
    input  logic                rst,
    input  logic                in_valid,
    output logic                in_ready,
    input  logic [4*UNIT_W-1:0] in_data,
    output logic                out_valid,
    input  logic                out_ready,
    output logic [3*UNIT_W-1:0] out_data
);
    localparam integer CAPACITY = 8 * UNIT_W;
    logic [3:0] count, after_pop;
    logic push, pop;

    assign out_valid = count >= 4'd3;
    assign pop = out_valid && out_ready;
    assign after_pop = pop ? count - 4'd3 : count;
    assign in_ready = !rst && after_pop <= 4'd4;
    assign push = in_valid && in_ready;

    always_ff @(posedge clk) begin
        if (rst)
            count <= '0;
        else
            count <= after_pop + (push ? 4'd4 : 4'd0);
    end

    logic [CAPACITY-1:0] pending, remaining;
    assign out_data = out_valid ? pending[3*UNIT_W-1:0] : '0;
    assign remaining = pop ? pending >> (3*UNIT_W) : pending;

    always_ff @(posedge clk) begin
        if (rst)
            pending <= '0;
        else if (push)
            pending <= remaining | (CAPACITY'(in_data) << (after_pop * UNIT_W));
        else
            pending <= remaining;
    end
endmodule

module secded_ecc #(
    parameter integer DATA_W = 16,
    localparam integer PARITY_W = (DATA_W <= 4) ? 3 : (DATA_W <= 11) ? 4
                                 : (DATA_W <= 26) ? 5 : 6
) (
    input  logic [DATA_W-1:0]        enc_data,
    output logic [DATA_W+PARITY_W:0] enc_code,
    input  logic [DATA_W+PARITY_W:0] dec_code,
    output logic [DATA_W-1:0]        dec_data,
    output logic                     corrected,
    output logic                     uncorrectable
);
    localparam integer H = DATA_W + PARITY_W;


    function automatic logic [PARITY_W-1:0] syndrome(input logic [H-1:0] bits);
        logic [PARITY_W-1:0] value;
        begin
            value = '0;
            for (integer pos = 1; pos <= H; pos = pos + 1)
                value = value ^ (PARITY_W'(pos) & {PARITY_W{bits[pos-1]}});
            syndrome = value;
        end
    endfunction

    function automatic logic [H:0] encode(input logic [DATA_W-1:0] data);
        logic [H-1:0] body;
        logic [PARITY_W-1:0] checks;
        integer i;
        begin
            body = '0;
            i = 0;
            for (integer pos = 1; pos <= H; pos = pos + 1) begin
                if ((pos & (pos-1)) != 0) begin
                    body[pos-1] = data[i];
                    i = i + 1;
                end
            end
            checks = syndrome(body);
            for (integer k = 0; k < PARITY_W; k = k + 1)
                body[(1 << k)-1] = checks[k];
            encode = {^body, body};
        end
    endfunction

    function automatic logic [DATA_W-1:0] decode_data(
        input logic [H-1:0] body,
        input logic [PARITY_W-1:0] flip_position
    );
        integer i;
        begin
            i = 0;
            for (integer pos = 1; pos <= H; pos = pos + 1) begin
                if ((pos & (pos-1)) != 0) begin
                    decode_data[i] = body[pos-1] ^ (flip_position == PARITY_W'(pos));
                    i = i + 1;
                end
            end
        end
    endfunction

    logic [PARITY_W-1:0] syn;
    logic odd;
    logic in_range;

    assign enc_code = encode(enc_data);
    assign syn = syndrome(dec_code[H-1:0]);
    assign odd = ^dec_code;

    assign in_range = int'(syn) <= H;
    assign corrected = odd && in_range;
    assign uncorrectable = (odd && !in_range) || (!odd && (syn != '0));
    assign dec_data = decode_data(dec_code[H-1:0], corrected ? syn : '0);
endmodule
